797	const OTHER_STATES = ['emphasis', 'blur', 'select'] as const;
798	const defaultStyleGetterMap: Dictionary<'getItemStyle' | 'getLineStyle' | 'getAreaStyle'> = {
799	    itemStyle: 'getItemStyle',
800	    lineStyle: 'getLineStyle',
801	    areaStyle: 'getAreaStyle'
