183	/**
184	 * If we reuse elements when rerender.
185	 * DON'T forget to clearStates before we update the style and shape.
186	 * Or we may update on the wrong state instead of normal state.
187	 */
188	export function clearStates(el: Element) {
189	    if (el.isGroup) {
190	        el.traverse(function (child) {
191	            child.clearStates();
192	        });
193	    }
194	    else {
195	        el.clearStates();
196	    }
197	}
