199	function getFromStateStyle(
200	    el: Displayable,
201	    props: (keyof PathStyleProps)[],
202	    toStateName: string,
203	    defaultValue?: PathStyleProps
204	): PathStyleProps {
205	    const style = el.style;
206	    const fromState: PathStyleProps = {};
207	    for (let i = 0; i < props.length; i++) {
208	        const propName = props[i];
209	        const val = style[propName];
210	        (fromState as any)[propName] = val == null ? (defaultValue && defaultValue[propName]) : val;
211	    }
212	    for (let i = 0; i < el.animators.length; i++) {
213	        const animator = el.animators[i];
214	        if (animator.__fromStateTransition
215	            // Don't consider the animation to emphasis state.
216	            && animator.__fromStateTransition.indexOf(toStateName) < 0
217	            && animator.targetName === 'style') {
218	            animator.saveTo(fromState, props);
219	        }
220	    }
221	    return fromState;
222	}
223	
224	function createEmphasisDefaultState(
225	    el: Displayable,
226	    stateName: 'emphasis',
227	    targetStates: string[],
228	    state: Displayable['states'][number]
229	): DisplayableState {
230	    const hasSelect = targetStates && indexOf(targetStates, 'select') >= 0;
231	    let cloned = false;
232	    if (el instanceof Path) {
233	        const store = getSavedStates(el);
234	        const fromFill = hasSelect ? (store.selectFill || store.normalFill) : store.normalFill;
235	        const fromStroke = hasSelect ? (store.selectStroke || store.normalStroke) : store.normalStroke;
236	        if (hasFillOrStroke(fromFill) || hasFillOrStroke(fromStroke)) {
237	            state = state || {};
238	            let emphasisStyle = state.style || {};
239	
240	            // inherit case
241	            if (emphasisStyle.fill === 'inherit') {
242	                cloned = true;
243	                state = extend({}, state);
244	                emphasisStyle = extend({}, emphasisStyle);
245	                emphasisStyle.fill = fromFill;
246	            }
247	            // Apply default color lift
248	            else if (!hasFillOrStroke(emphasisStyle.fill) && hasFillOrStroke(fromFill)) {
249	                cloned = true;
250	                // Not modify the original value.
251	                state = extend({}, state);
252	                emphasisStyle = extend({}, emphasisStyle);
253	                // Already being applied 'emphasis'. DON'T lift color multiple times.
254	                emphasisStyle.fill = liftColor(fromFill as ColorString);
255	            }
256	            // Not highlight stroke if fill has been highlighted.
257	            else if (!hasFillOrStroke(emphasisStyle.stroke) && hasFillOrStroke(fromStroke)) {
258	                if (!cloned) {
259	                    state = extend({}, state);
260	                    emphasisStyle = extend({}, emphasisStyle);
261	                }
262	                emphasisStyle.stroke = liftColor(fromStroke as ColorString);
263	            }
264	            state.style = emphasisStyle;
265	        }
266	    }
267	    if (state) {
268	        // TODO Share with textContent?
269	        if (state.z2 == null) {
270	            if (!cloned) {
271	                state = extend({}, state);
272	            }
273	            const z2EmphasisLift = (el as ECElement).z2EmphasisLift;
274	            state.z2 = el.z2 + (z2EmphasisLift != null ? z2EmphasisLift : Z2_EMPHASIS_LIFT);
275	        }
276	    }
277	    return state;
278	}
279	
280	function createSelectDefaultState(
281	    el: Displayable,
282	    stateName: 'select',
283	    state: Displayable['states'][number]
284	): DisplayableState {
285	    // const hasSelect = indexOf(el.currentStates, stateName) >= 0;
286	    if (state) {
287	        // TODO Share with textContent?
288	        if (state.z2 == null) {
289	            state = extend({}, state);
290	            const z2SelectLift = (el as ECElement).z2SelectLift;
291	            state.z2 = el.z2 + (z2SelectLift != null ? z2SelectLift : Z2_SELECT_LIFT);
292	        }
293	    }
294	    return state;
295	}
296	
297	function createBlurDefaultState(
298	    el: Displayable,
299	    stateName: 'blur',
300	    state: Displayable['states'][number]
301	): DisplayableState {
302	    const hasBlur = indexOf(el.currentStates, stateName) >= 0;
303	    const currentOpacity = el.style.opacity;
304	
305	    const fromState = !hasBlur
306	        ? getFromStateStyle(el, ['opacity'], stateName, {
307	            opacity: 1
308	        })
309	        : null;
310	
311	    state = state || {};
312	    let blurStyle = state.style || {};
313	    if (blurStyle.opacity == null) {
314	        // clone state
315	        state = extend({}, state);
316	        blurStyle = extend({
317	            // Already being applied 'emphasis'. DON'T mul opacity multiple times.
318	            opacity: hasBlur ? currentOpacity : (fromState.opacity * 0.1)
319	        }, blurStyle);
320	        state.style = blurStyle;
321	    }
322	
323	    return state;
324	}
325	
326	function elementStateProxy(this: Displayable, stateName: string, targetStates?: string[]): DisplayableState {
327	    const state = this.states[stateName];
328	    if (this.style) {
329	        if (stateName === 'emphasis') {
330	            return createEmphasisDefaultState(this, stateName, targetStates, state);
331	        }
332	        else if (stateName === 'blur') {
333	            return createBlurDefaultState(this, stateName, state);
334	        }
335	        else if (stateName === 'select') {
336	            return createSelectDefaultState(this, stateName, state);
337	        }
338	    }
339	    return state;
340	}
341	
342	/**
343	 * Set hover style (namely "emphasis style") of element.
